<script setup>
import { ref,onMounted,onUnmounted } from 'vue';
import { api,label,time } from './api';
const ops=ref(),audits=ref([]),tab=ref('jobs'),busy=ref(false);let timer;
async function load(quiet=false){ops.value=await api('/operations',{quiet});audits.value=await api('/audit-events',{quiet});}
async function retry(kind,id){busy.value=true;try{await api(`/operations/${kind}/${id}/retry`,{method:'POST'});await load();}finally{busy.value=false;}}
onMounted(async()=>{await load();timer=setInterval(()=>load(true).catch(()=>{}),8000);});onUnmounted(()=>clearInterval(timer));
</script>
<template><section class="page-heading"><div><div class="eyebrow">OPERATIONS & AUDIT</div><h1>运行与审计</h1><p>查看失败任务、接入待确认记录和关键操作轨迹。</p></div><button @click="load">↻ 刷新</button></section><div class="stat-grid" v-if="ops"><div class="stat-card"><span>待派发任务</span><strong>{{ ops.pendingOutbox }}</strong></div><div class="stat-card"><span>失败 / 待人工处理</span><strong>{{ ops.jobs.filter(j=>['failed','waiting_input','finalizing'].includes(j.status)).length }}</strong></div><div class="stat-card"><span>接入待确认</span><strong>{{ ops.events.filter(e=>e.status==='waiting_confirmation').length }}</strong></div><div class="stat-card"><span>最近备份</span><b>{{ ops.backup?.lastSuccess?time(ops.backup.lastSuccess):'尚无成功记录' }}</b><small>{{ ops.backup?.restoreTested?'已记录恢复演练':'需完成恢复演练' }}</small></div></div><div class="tabs"><button v-for="t in [{id:'jobs',name:'预审任务'},{id:'events',name:'钉钉接入'},{id:'audit',name:'操作日志'}]" :key="t.id" @click="tab=t.id" :class="{active:tab===t.id}">{{ t.name }}</button></div><section class="panel" v-if="ops"><div class="table-scroll"><table v-if="tab==='jobs'"><thead><tr><th>任务 ID</th><th>状态</th><th>步骤 / 进度</th><th>异常</th><th>更新时间</th><th></th></tr></thead><tbody><tr v-for="j in ops.jobs" :key="j.id"><td class="mono">{{ j.id }}</td><td><span class="badge" :class="j.status">{{ label(j.status) }}</span></td><td>{{ j.stage }} · {{ j.progress }}%</td><td>{{ j.error_code }}<small>{{ j.error_message }}</small></td><td>{{ time(j.updated_at) }}</td><td><button v-if="['failed','waiting_input','finalizing'].includes(j.status)" @click="retry('reviews',j.id)" :disabled="busy">重试原任务</button></td></tr></tbody></table><table v-else-if="tab==='events'"><thead><tr><th>事件 ID</th><th>类型</th><th>状态</th><th>收取结果 / 原因</th><th></th></tr></thead><tbody><tr v-for="e in ops.events" :key="e.id"><td class="mono">{{ e.id }}</td><td>{{ e.event_type }}</td><td>{{ e.status }}</td><td><template v-if="e.summary">新增 {{ e.summary.collected||0 }} · 重复 {{ e.summary.duplicate||0 }} · 跳过 {{ e.summary.skipped||0 }} · 失败 {{ e.summary.failed||0 }}<small>{{ e.summary.reason }}</small></template><small>{{ e.error }}</small></td><td><button v-if="e.status==='waiting_confirmation'" @click="retry('events',e.id)" :disabled="busy">重新接入</button></td></tr></tbody></table><table v-else><thead><tr><th>时间</th><th>操作人 ID</th><th>动作</th><th>对象</th><th>操作信息</th></tr></thead><tbody><tr v-for="a in audits" :key="a.id"><td class="nowrap">{{ time(a.created_at) }}</td><td class="mono">{{ a.actor_id }}</td><td>{{ a.action }}</td><td class="mono">{{ a.entity_id }}</td><td><code>{{ a.details }}</code></td></tr></tbody></table></div></section></template>

